    let phaseIndex = 0;
    const phaseInterval = setInterval(() => {
      if (phaseIndex < phases.length) {
        setScanPhase(phases[phaseIndex]);
        phaseIndex++;
      }
    }, 1200);

    try {
      const res = await fetch("/api/guardian/scan", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(scanData)
