                  {expandedSection === "timeline" ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
                </button>

                {expandedSection === "timeline" && (
                  <div className="px-3 lg:px-6 pb-4 lg:pb-6 grid grid-cols-3 gap-2 lg:gap-3">
                    {timelines.map((timeline) => (
                      <button
