  }

  .btn-glow::before {
    display: none;
  }

  .btn-glow:hover::before {
    display: none;
  }

  .btn-glow:hover {
    opacity: 0.9;
  }

  .gradient-text {
    color: hsl(230 55% 58%);
    -webkit-text-fill-color: hsl(230 55% 58%);
  }

  .gradient-border {
    position: relative;
