        cancel_url: `${baseUrl}/hub`,
        metadata: {
          items: JSON.stringify(items.map((i: any) => ({ id: i.id, name: i.name, type: i.type }))),
          purchase_type: "hub_widgets",
          download_token: downloadToken,
