        customerEmail: "pending@checkout.com",
        items: JSON.stringify(items.map((i: any) => ({ id: i.id, name: i.name, type: i.type }))),
        totalAmount,
        status: "pending",
        downloadToken,
        paymentMethod: "stripe",
      });

      res.json({ success: true, url: session.url });
