    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/marketing/posts"] });
      toast({ title: "Post deleted" });
    }
  });

  const postNowMutation = useMutation({
    mutationFn: async (data: { content: string; platform: string }) => {
