    .tl-lead-buttons { display: flex; gap: 12px; margin-top: 24px; }\
    .tl-lead-btn { flex: 1; padding: 14px; font-size: 16px; font-weight: 600; border-radius: 10px; cursor: pointer; transition: all 0.2s; }\
